def decode_string(s: str) -> str:
    stack = []
    cur = []
    num = 0

    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == '[':
            stack.append((num, ''.join(cur)))
            num = 0
            cur = []
        elif ch == ']':
            k, prev = stack.pop()
            cur = [prev + ''.join(cur) * k]
        else:
            cur.append(ch)

    return ''.join(cur)
