from collections import deque


def count_islands(grid: list[list[str]]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    visited = set()
    islands = 0
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == "1" and (r, c) not in visited:
                islands += 1
                queue = deque([(r, c)])
                visited.add((r, c))

                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if (
                            0 <= nr < rows
                            and 0 <= nc < len(grid[nr])
                            and grid[nr][nc] == "1"
                            and (nr, nc) not in visited
                        ):
                            visited.add((nr, nc))
                            queue.append((nr, nc))

    return islands
```

