def word_break(s: str, words: list[str]) -> bool:
    if not s:
        return True

    word_set = {w for w in words if w}
    if not word_set:
        return False

    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break

    return dp[n]
```

